var positive_width = distance10.pipe(numberType().finite().positive());
var pcb_trace_route_point_wire2 = objectType({
  route_type: literalType("wire"),
  x: distance10,
  y: distance10,
  width: distance10,
  start_width: positive_width.optional(),
  end_width: positive_width.optional(),
  width_interpolation_mode: enumType(["linear", "quadratic"]).optional(),
  copper_pour_id: stringType().optional(),
  is_inside_copper_pour: booleanType().optional(),
  start_pcb_port_id: stringType().optional(),
  end_pcb_port_id: stringType().optional(),
  layer: layer_ref2
}).superRefine((wire, ctx) => {
  const present = [
    wire.start_width,
    wire.end_width,
    wire.width_interpolation_mode
  ].filter((v) => v !== undefined).length;
  if (present === 0)
    return;
  if (present !== 3) {
    ctx.addIssue({
      code: ZodIssueCode.custom,
      message: "Wire taper requires start_width, end_width and width_interpolation_mode together"
    });
  }
  if (wire.width !== wire.start_width) {
    ctx.addIssue({
      code: ZodIssueCode.custom,
      path: ["start_width"],
      message: "start_width must equal width"
    });
  }
  if (!Number.isFinite(wire.x) || !Number.isFinite(wire.y)) {
    ctx.addIssue({
      code: ZodIssueCode.custom,
      message: "Tapered wire coordinates must be finite"
    });
  }
});
