var pcb_trace2 = objectType({
  type: literalType("pcb_trace"),
  source_trace_id: stringType().optional(),
  pcb_component_id: stringType().optional(),
  pcb_trace_id: getZodPrefixedIdWithDefault2("pcb_trace"),
  pcb_group_id: stringType().optional(),
  subcircuit_id: stringType().optional(),
  route_thickness_mode: enumType(["constant", "interpolated"]).default("constant").optional(),
  route_order_index: numberType().optional(),
  should_round_corners: booleanType().optional(),
  trace_length: numberType().optional(),
  is_antenna_trace: booleanType().optional(),
  highlight_color: stringType().optional(),
  route: arrayType(pcb_trace_route_point2).superRefine((route, ctx) => {
    for (const [i, wire] of route.entries()) {
      if (wire.route_type !== "wire" || wire.width_interpolation_mode === undefined)
        continue;
      const next = route[i + 1];
      const end = next?.route_type === "through_pad" ? next.start : next;
      const layer = next?.route_type === "wire" ? next.layer : next?.route_type === "via" ? next.from_layer : next?.start_layer;
      const length4 = end ? Math.hypot(end.x - wire.x, end.y - wire.y) : NaN;
      if (!Number.isFinite(length4) || length4 <= 0 || layer !== wire.layer) {
        ctx.addIssue({
          code: ZodIssueCode.custom,
          path: [i],
          message: "Tapered wire must lead to a distinct finite next point on the same layer"
        });
      }
    }
  })
}).describe("Defines a trace on the PCB");
expectTypesMatch2(true);
