// lib/autorouter-pipelines/AutoroutingPipeline9_PreloadedTraceGraph/convertPreloadedTraceToHdRoutes.ts
var MIN_ROUTE_DIMENSION = 0.000000001;
var convertPreloadedTraceToHdRoutes = (trace, traceIndex, layerCount, defaultViaDiameter, connMap) => {
  const rootConnectionName = connMap.getNetConnectedToId(trace.connection_name) ?? trace.connection_name;
  const routes = [];
  const addRoute = (route, traceThickness, viaDiameter = defaultViaDiameter, vias = [], routePositionStart, routePositionEnd, isThroughObstacle = false) => {
    if (route.length < 2)
      return;
    routes.push({
      connectionName: `${trace.connection_name}_fixed_${traceIndex}_${routes.length}`,
      rootConnectionName,
      isFixed: trace.isFixed,
      preloadedTraceIndex: traceIndex,
      preloadedRouteIndex: routes.length,
      preloadedRoutePositionStart: routePositionStart,
      preloadedRoutePositionEnd: routePositionEnd,
      isThroughObstacle,
      traceThickness: Math.max(MIN_ROUTE_DIMENSION, traceThickness),
      viaDiameter: Math.max(MIN_ROUTE_DIMENSION, viaDiameter),
      route,
      vias
    });
  };
  for (let pointIndex = 0;pointIndex < trace.route.length; pointIndex++) {
    const point = trace.route[pointIndex];
    if (point.route_type === "via") {
      addRoute([
        {
          x: point.x,
          y: point.y,
          z: mapLayerNameToZ2(point.from_layer, layerCount)
        },
        {
          x: point.x,
          y: point.y,
          z: mapLayerNameToZ2(point.to_layer, layerCount)
        }
      ], MIN_ROUTE_DIMENSION, point.via_diameter ?? defaultViaDiameter, [{ x: point.x, y: point.y }], pointIndex, pointIndex);
      continue;
    }
    if (point.route_type === "through_obstacle") {
      const fromZ = mapLayerNameToZ2(point.from_layer, layerCount);
      const toZ = mapLayerNameToZ2(point.to_layer, layerCount);
      for (let z = Math.min(fromZ, toZ);z <= Math.max(fromZ, toZ); z++) {
        addRoute([
          { ...point.start, z },
          { ...point.end, z }
        ], point.width, defaultViaDiameter, [], pointIndex, pointIndex + 1, true);
      }
      continue;
    }
    const nextPoint = trace.route[pointIndex + 1];
    if (point.route_type !== "wire" || nextPoint?.route_type !== "wire" || point.layer !== nextPoint.layer) {
      continue;
    }
    addRoute([
      {
        x: point.x,
        y: point.y,
        z: mapLayerNameToZ2(point.layer, layerCount)
      },
      {
        x: nextPoint.x,
        y: nextPoint.y,
        z: mapLayerNameToZ2(nextPoint.layer, layerCount)
      }
    ], Math.max(point.width, nextPoint.width), defaultViaDiameter, [], pointIndex, pointIndex + 1);
  }
  return routes;
};

