function getFixedCopperObstacleIndexes({
  inputSrj,
  representedPadObstacleIndexes
}) {
  const fixedCopperObstacleIndexes = new Set;
  for (const [obstacleIndex, obstacle] of inputSrj.obstacles.entries()) {
    if (!representedPadObstacleIndexes.has(obstacleIndex) && obstacle.connectedTo.length > 0 && !obstacle.isCopperPour && !obstacle.isNonPlatedHole) {
      fixedCopperObstacleIndexes.add(obstacleIndex);
    }
  }
  return fixedCopperObstacleIndexes;
}

