class QfpThermalPadTopologyGeneratorSolver extends BaseSolver3 {
  inputProblem;
  static componentKind = "qfp_thermalpad";
  output = null;
  constructor(inputProblem) {
    super();
    this.inputProblem = inputProblem;
  }
  getConstructorParams() {
    return [this.inputProblem];
  }
  _step() {
    if (this.output) {
      this.solved = true;
      return;
    }
    const { layerCount, obstacles } = this.inputProblem.inputSrj;
    const { bounds, componentId } = this.inputProblem.detectedComponent;
    const availableZ = getLayerRange(layerCount);
    const topologyObstacles = obstacles.filter((obstacle) => obstacle.componentId === componentId);
    const componentObstacles = topologyObstacles.length > 0 ? topologyObstacles : obstacles;
    const { padRingObstacles, thermalPadObstacles } = splitQfpThermalPadObstacles(componentObstacles);
    const sideGroups = groupObstaclesBySide(padRingObstacles, bounds);
    const innerBounds = getInnerQfpBounds({ bounds, sideGroups });
    const thermalPadBounds = combineObstacleBounds(thermalPadObstacles);
    if (!thermalPadBounds) {
      this.failed = true;
      this.error = "QfpThermalPadTopologyGeneratorSolver requires a thermal pad";
      return;
    }
    const nodeScopeId = componentId;
    const viaDiameter = this.inputProblem.viaDiameter ?? getViaDimensions(this.inputProblem.inputSrj).padDiameter;
    const obstacleMargin = this.inputProblem.obstacleMargin ?? this.inputProblem.inputSrj.defaultObstacleMargin ?? 0.15;
    const multiLayerThreshold = viaDiameter + obstacleMargin * 2;
    const narrowPadGapThreshold = this.inputProblem.inputSrj.minTraceWidth + obstacleMargin * 2;
    const regions = [
      ...getPadRegions(padRingObstacles, layerCount),
      ...getThermalPadRegions(thermalPadObstacles, layerCount),
      ...createOuterGapRegionsForSide({
        side: "top",
        sideObstacles: sideGroups.top,
        bounds,
        innerBounds,
        narrowThreshold: narrowPadGapThreshold
      }),
      ...createOuterGapRegionsForSide({
        side: "right",
        sideObstacles: sideGroups.right,
        bounds,
        innerBounds,
        narrowThreshold: narrowPadGapThreshold
      }),
      ...createOuterGapRegionsForSide({
        side: "bottom",
        sideObstacles: sideGroups.bottom,
        bounds,
        innerBounds,
        narrowThreshold: narrowPadGapThreshold
      }),
      ...createOuterGapRegionsForSide({
        side: "left",
        sideObstacles: sideGroups.left,
        bounds,
        innerBounds,
        narrowThreshold: narrowPadGapThreshold
      }),
      ...createInnerPadClearanceRegionsForSide({
        side: "top",
        sideObstacles: sideGroups.top,
        thermalPadBounds,
        narrowThreshold: narrowPadGapThreshold
      }),
      ...createInnerPadClearanceRegionsForSide({
        side: "right",
        sideObstacles: sideGroups.right,
        thermalPadBounds,
        narrowThreshold: narrowPadGapThreshold
      }),
      ...createInnerPadClearanceRegionsForSide({
        side: "bottom",
        sideObstacles: sideGroups.bottom,
        thermalPadBounds,
        narrowThreshold: narrowPadGapThreshold
      }),
      ...createInnerPadClearanceRegionsForSide({
        side: "left",
        sideObstacles: sideGroups.left,
        thermalPadBounds,
        narrowThreshold: narrowPadGapThreshold
      }),
      ...getInnerCornerRegions({
        innerBounds,
        thermalPadBounds,
        sideGroups
      }),
      ...getOuterCornerRegions({ bounds, innerBounds, sideGroups })
    ];
    const routingRegions = regions.flatMap((region) => createMeshNodesForRegion({
      nodeId: `qfp_thermalpad:${nodeScopeId}:${region.key}`,
      bounds: region.bounds,
      availableZ,
      multiLayerThreshold,
      regionType: region.regionType,
      isNarrowPadGap: region.isNarrowPadGap,
      obstacleZ: region.obstacleZ,
      connectedTo: region.connectedTo
    }));
    this.output = {
      routingRegions
    };
    this.stats = {
      componentId,
      layerCount,
      viaDiameter,
      obstacleMargin,
      multiLayerThreshold,
      narrowPadGapThreshold,
      thermalPadCount: thermalPadObstacles.length,
      perimeterPadCount: padRingObstacles.length,
      innerCornerRectCount: routingRegions.filter((node) => node.capacityMeshNodeId.includes(":inner-corner-")).length,
      narrowPadGapNodeCount: routingRegions.filter((node) => node._isNarrowQfpPadGap).length,
      topPadCount: sideGroups.top.length,
      rightPadCount: sideGroups.right.length,
      bottomPadCount: sideGroups.bottom.length,
      leftPadCount: sideGroups.left.length,
      multiLayerNodeCount: routingRegions.filter((node) => node.availableZ.length > 1).length,
      totalMeshNodeCount: routingRegions.length
    };
    this.solved = true;
  }
  getOutput() {
    if (!this.output) {
      throw new Error("QfpThermalPadTopologyGeneratorSolver has not solved yet");
    }
    return this.output;
  }
}
TopologyGenerator.register(QfpThermalPadTopologyGeneratorSolver);

