// lib/solvers/ComponentDetectionSolver/detectors/soic/SoicComponentDetector.ts
var MIN_SOIC_SHORT_AXIS_COUNT = 2;
var MIN_SOIC_LONG_AXIS_COUNT = 4;
var MAX_SOIC_PAD_SIZE_VARIANCE = 0.01;
