      duplicateCongestedPortCount: this.duplicatedPortCount,
      duplicateCongestedPortFallbackToOriginal: Boolean(this.duplicateCongestedPortError),
      duplicateCongestedPortPenalty: this.duplicatedPortCount > 0 ? DUPLICATE_PORT_TRAVERSAL_PENALTY : 0,
      duplicateCongestedPortPenaltyCount: this.tinyPipelineSolver.duplicatePortPenaltyCount,
