// lib/utils/getMinDistBetweenEnteringPoints.ts
var getMinDistBetweenEnteringPoints = (node) => {
  let minDist = Infinity;
  const points = node.portPoints;
  for (let i = 0;i < points.length; i++) {
    for (let j = i + 1;j < points.length; j++) {
      const p1 = points[i];
      const p2 = points[j];
      if (p1.z !== p2.z) {
        continue;
      }
      if (p1.rootConnectionName && p1.rootConnectionName === p2.rootConnectionName) {
        continue;
      }
      const dist = Math.sqrt((p1.x - p2.x) ** 2 + (p1.y - p2.y) ** 2);
      minDist = Math.min(minDist, dist);
    }
  }
  return minDist === Infinity ? 0 : minDist;
};

// lib/solvers/HighDensitySolver/precomputeIntraNodeRouteParams.ts
var precomputeIntraNodeRouteParams = (node) => {
  const connectionPointsByName = new Map;
  const rootConnectionNameByConnectionName = new Map;
  const seenPointsByConnectionName = new Map;
  for (const {
    connectionName,
    rootConnectionName,
    x,
    y,
    z
  } of node.portPoints) {
    if (rootConnectionName) {
      rootConnectionNameByConnectionName.set(connectionName, rootConnectionName);
    }
    let points = connectionPointsByName.get(connectionName);
    let seenPoints = seenPointsByConnectionName.get(connectionName);
    if (!points || !seenPoints) {
      points = [];
      seenPoints = new Set;
      connectionPointsByName.set(connectionName, points);
      seenPointsByConnectionName.set(connectionName, seenPoints);
    }
    const layer = z ?? 0;
    const key = `${x.toFixed(6)},${y.toFixed(6)},${layer}`;
    if (seenPoints.has(key))
      continue;
    seenPoints.add(key);
    points.push({ x, y, z: layer });
  }
  return {
    connectionPointsByName,
    rootConnectionNameByConnectionName,
    minDistBetweenEnteringPoints: getMinDistBetweenEnteringPoints(node)
  };
};

// lib/solvers/HighDensitySolver/IntraNodeSolver.ts
