      D: routeA.endPort,
      E: routeB.startPort,
      F: routeB.endPort,
      radius: this.viaDiameter / 2 + this.obstacleMargin + this.traceThickness / 2 * NOT_CIRCULAR_PENALTY_TC,
      margin: this.obstacleMargin * 2 + this.traceThickness / 2 * NOT_CIRCULAR_PENALTY_TC,
      subdivisions: 1
