  solvedRoutes = [];
  nodeWithPortPoints;
  connMap;
  effort;
  adaptiveSearchExpanded = false;
  negotiatedSearchStarted = false;
  enableNegotiatedSearch;
  gridSearchSegmentWork;
  gridSearchWorkScale;
  rejectOverlappingTerminals;
  precomputedIntraNodeRouteParams;
  nodeSegmentCount;
  totalCandidateWork = 0;
  dynamicExpansionWorkBudget = 1;
  candidateWorkBySolver = new WeakMap;
  getSolvedSegmentCount(solver) {
    const solvedConnectionsMap = solver.solvedConnectionsMap;
    if (!(solvedConnectionsMap instanceof Map))
      return null;
    let solvedSegmentCount = 0;
    for (const routes of solvedConnectionsMap.values()) {
      if (Array.isArray(routes))
        solvedSegmentCount += routes.length;
    }
    return solvedSegmentCount;
  }
  getNodeSegmentCount() {
    this.nodeSegmentCount ??= Math.max(1, this.nodeWithPortPoints.portPointsInPairs?.length ?? new Set(this.nodeWithPortPoints.portPoints.map((portPoint) => portPoint.connectionName)).size);
    return this.nodeSegmentCount;
  }
