// lib/autorouter-pipelines/AutoroutingPipeline9_PreloadedTraceGraph/canPublishPartialFixedObstacleRepair.ts
var canPublishPartialFixedObstacleRepair = ({
  originalSrj,
  initialErrors,
  remainingErrors
}) => {
  if (remainingErrors.length >= initialErrors.length)
    return false;
  if (remainingErrors.length === 0)
    return true;
  const padIds = new Set(createPcbPadElements2(originalSrj).flatMap((element) => element.type === "pcb_smtpad" ? [element.pcb_smtpad_id] : element.type === "pcb_plated_hole" ? [element.pcb_plated_hole_id] : []));
  const unmatchedErrors = [...initialErrors];
  for (const error of remainingErrors) {
    if (typeof error.pcb_trace_id !== "string")
      return false;
    const prefix = `overlap_${error.pcb_trace_id}_`;
    const overlapPadId = error.type === "pcb_trace_error" && typeof error.pcb_trace_error_id === "string" && error.pcb_trace_error_id.startsWith(prefix) ? error.pcb_trace_error_id.slice(prefix.length) : undefined;
    const isViaPadClearance = isViaPadClearanceError(error);
    const isPadClearance = error.type === "pcb_pad_trace_clearance_error" || isViaPadClearance;
    const padId = isViaPadClearance ? error.pcb_pad_ids.find((id) => padIds.has(id)) : isPadClearance ? error.pcb_pad_id : overlapPadId;
    if (typeof padId !== "string" || !padIds.has(padId))
      return false;
    const originalIndex = unmatchedErrors.findIndex((original) => original.type === error.type && original.pcb_trace_id === error.pcb_trace_id && (isViaPadClearance ? isViaPadClearanceError(original) && original.pcb_pad_ids.includes(padId) : isPadClearance ? original.pcb_pad_id === padId : original.pcb_trace_error_id === error.pcb_trace_error_id));
    if (originalIndex === -1)
      return false;
    const original = unmatchedErrors.splice(originalIndex, 1)[0];
    if (isPadClearance && (typeof error.actual_clearance !== "number" || !Number.isFinite(error.actual_clearance) || typeof original.actual_clearance !== "number" || !Number.isFinite(original.actual_clearance) || typeof error.minimum_clearance !== "number" || !Number.isFinite(error.minimum_clearance) || error.minimum_clearance !== original.minimum_clearance || error.actual_clearance < original.actual_clearance)) {
      return false;
    }
  }
  return true;
};

