// lib/autorouter-pipelines/AutoroutingPipeline7_MultiGraph/PowerTraceExpansionSolver.ts
class PowerTraceExpansionSolver extends BaseSolver2 {
  inputSrj;
  options;
  powerTraceExpanderSolver;
  constructor(inputSrj, options = {}) {
    super();
    this.inputSrj = inputSrj;
    this.options = options;
    this.powerTraceExpanderSolver = new PowerTraceExpanderSolver({
      ...inputSrj,
      minViaEdgeToPadEdgeClearance: getViaToPadClearance(inputSrj)
    }, options);
    if (options.onlyConnectionNames?.length === 0) {
      this.MAX_ITERATIONS = 1;
      this.progress = 1;
      this.solved = true;
      this.stats = { selectedTraceCount: 0, bypassed: true };
      return;
    }
    this.MAX_ITERATIONS = this.powerTraceExpanderSolver.MAX_ITERATIONS + 1;
  }
  _step() {
    const solver = this.powerTraceExpanderSolver;
    solver.step();
    this.progress = solver.progress;
    this.stats = solver.stats;
    if (solver.failed) {
      this.error = solver.error;
      this.failed = true;
      return;
    }
    if (solver.solved)
      this.solved = true;
  }
  getConstructorParams() {
    return [this.inputSrj, this.options];
  }
  getOutput() {
    if (!this.solved) {
      throw new Error("Cannot get power trace expansion output before solving");
    }
    return this.powerTraceExpanderSolver.getOutput();
  }
  visualize() {
    return convertSrjToGraphicsObject({
      ...this.inputSrj,
      traces: this.getOutput()
    }, { traceColorMode: "layer" });
  }
}

// lib/autorouter-pipelines/AutoroutingPipeline7_MultiGraph/getPowerTraceExpansionConnectionNames.ts
var MINIMUM_POWER_WIDTH_INCREASE_MM = 0.1;
var MINIMUM_POWER_WIDTH_RATIO = 2;
var getPowerTraceExpansionConnectionNames = (srj) => {
  const minimumPowerWidth = Math.max(srj.minTraceWidth + MINIMUM_POWER_WIDTH_INCREASE_MM, srj.minTraceWidth * MINIMUM_POWER_WIDTH_RATIO);
  return srj.connections.flatMap((connection) => {
    const nominalWidth = connection.nominalTraceWidth ?? srj.nominalTraceWidth ?? srj.minTraceWidth;
    return nominalWidth + 0.000001 >= minimumPowerWidth ? [connection.name] : [];
  });
};

// lib/autorouter-pipelines/AutoroutingPipeline7_MultiGraph/lock-hd-route-terminals.ts
var lockHdRouteTerminals = ({
  hdRoutes,
  connections
}) => {
  const connectionByName = new Map(connections.map((connection) => [connection.name, connection]));
  return hdRoutes.map((hdRoute) => {
    if (hdRoute.route.length === 0) {
      throw new Error(`Cannot lock PCB terminals for empty route "${hdRoute.connectionName}"`);
    }
    const connection = connectionByName.get(hdRoute.connectionName);
    if (!connection) {
      throw new Error(`Cannot lock PCB terminals: connection "${hdRoute.connectionName}" was not found`);
    }
    if (connection.pointsToConnect.length !== 2) {
      throw new Error(`Cannot lock PCB terminals for "${hdRoute.connectionName}": expected 2 connection points, found ${connection.pointsToConnect.length}`);
    }
    const terminalByPcbPortId = new Map;
    for (const terminal of connection.pointsToConnect) {
      if (!terminal.pcb_port_id)
        continue;
      if (terminalByPcbPortId.has(terminal.pcb_port_id)) {
        throw new Error(`Cannot lock duplicate PCB terminal "${terminal.pcb_port_id}" for "${hdRoute.connectionName}"`);
      }
      terminalByPcbPortId.set(terminal.pcb_port_id, terminal);
    }
    if (terminalByPcbPortId.size === 0)
      return hdRoute;
    const routeEndpointPcbPortIds = [
      hdRoute.startPcbPortId,
      hdRoute.endPcbPortId
    ].filter((pcbPortId) => pcbPortId !== undefined);
    if (routeEndpointPcbPortIds.length === 0)
      return hdRoute;
    const uniqueRouteEndpointPcbPortIds = new Set(routeEndpointPcbPortIds);
    if (uniqueRouteEndpointPcbPortIds.size !== routeEndpointPcbPortIds.length || routeEndpointPcbPortIds.some((pcbPortId) => !terminalByPcbPortId.has(pcbPortId))) {
      throw new Error(`Cannot lock PCB terminals for "${hdRoute.connectionName}": route endpoint IDs do not match connection terminal IDs`);
    }
    const startTerminal = hdRoute.startPcbPortId ? terminalByPcbPortId.get(hdRoute.startPcbPortId) : undefined;
    const endTerminal = hdRoute.endPcbPortId ? terminalByPcbPortId.get(hdRoute.endPcbPortId) : undefined;
    const route = hdRoute.route.map((point, pointIndex) => {
      if (pointIndex === 0 && startTerminal) {
        return {
          ...point,
          x: startTerminal.x,
          y: startTerminal.y,
          pcb_port_id: startTerminal.pcb_port_id
        };
      }
      if (pointIndex === hdRoute.route.length - 1 && endTerminal) {
        return {
          ...point,
          x: endTerminal.x,
          y: endTerminal.y,
          pcb_port_id: endTerminal.pcb_port_id
        };
      }
      const interiorPoint = { ...point };
      delete interiorPoint.pcb_port_id;
      return interiorPoint;
    });
    return { ...hdRoute, route };
  });
};

// lib/autorouter-pipelines/AutoroutingPipeline7_MultiGraph/prepare-pipeline7-power-trace-expansion-input.ts
var preparePipeline7PowerTraceExpansionInput = ({
  originalSrj,
  newlyRoutedTraces,
  currentPreloadedTraces,
  expandedConnectionNames,
  resolveConnectedTraceAliases = false
}) => {
  const preloadedTraces = currentPreloadedTraces ?? originalSrj.traces ?? [];
  const mutablePreloadedTraceSet = resolveConnectedTraceAliases ? getConnectedMutablePreloadedTraces({
    originalSrj,
    newlyRoutedTraces,
    preloadedTraces,
    expandedConnectionNames
  }) : new Set(preloadedTraces.filter((trace) => expandedConnectionNames.includes(trace.connection_name)));
  for (const trace of preloadedTraces) {
    if (trace.isFixed)
      mutablePreloadedTraceSet.delete(trace);
  }
  const fixedTraces = preloadedTraces.filter((trace) => !mutablePreloadedTraceSet.has(trace));
  const usedTraceIds = new Set([
    ...newlyRoutedTraces.map((trace) => trace.pcb_trace_id),
    ...fixedTraces.map((trace) => trace.pcb_trace_id)
  ]);
  const mutablePreloadedTraces = preloadedTraces.filter((trace) => mutablePreloadedTraceSet.has(trace)).map((trace) => {
    const baseTraceId = trace.pcb_trace_id;
    let traceId = baseTraceId;
    let suffix = 2;
    while (usedTraceIds.has(traceId)) {
      traceId = `${baseTraceId}_power_expansion_${suffix++}`;
    }
    usedTraceIds.add(traceId);
    return {
      ...trace,
      pcb_trace_id: traceId,
      __replaces_pcb_trace_id: trace.__replaces_pcb_trace_id ?? trace.pcb_trace_id
    };
  });
  return {
    ...originalSrj,
    traces: [...newlyRoutedTraces, ...mutablePreloadedTraces],
    fixedTraces
  };
};
var getConnectedMutablePreloadedTraces = ({
  originalSrj,
  newlyRoutedTraces,
  preloadedTraces,
  expandedConnectionNames
}) => {
  const preloadedTraceIds = new Set(preloadedTraces.map((trace) => trace.pcb_trace_id));
  const resolverTraceIds = new Set([
    ...preloadedTraceIds,
    ...newlyRoutedTraces.map((trace) => trace.pcb_trace_id)
  ]);
  const resolverNewlyRoutedTraces = newlyRoutedTraces.map((trace, index) => {
    if (!preloadedTraceIds.has(trace.pcb_trace_id))
      return trace;
    const baseTraceId = `__pipeline7_new_trace_${index}_${trace.pcb_trace_id}`;
    let resolverTraceId = baseTraceId;
    let suffix = 2;
    while (resolverTraceIds.has(resolverTraceId)) {
      resolverTraceId = `${baseTraceId}_${suffix++}`;
    }
    resolverTraceIds.add(resolverTraceId);
    return { ...trace, pcb_trace_id: resolverTraceId };
  });
  const connectionNameResolver = new ConnectionNameResolver({
    ...originalSrj,
    traces: [...resolverNewlyRoutedTraces, ...preloadedTraces]
  });
  const expandedConnectionNameSet = new Set(connectionNameResolver.canonicalize([...expandedConnectionNames]));
  return new Set(preloadedTraces.filter((trace) => connectionNameResolver.canonicalize([trace.connection_name]).some((name) => expandedConnectionNameSet.has(name))));
};

// lib/autorouter-pipelines/AutoroutingPipeline9_PreloadedTraceGraph/AutoroutingPipelineSolver9_PreloadedTraceGraph.ts
function getComponentCapacityMeshNodeIds(capacityMeshNodes) {
  return new Set((capacityMeshNodes ?? []).filter((node) => node._isComponentTopologyNode).map((node) => node.capacityMeshNodeId));
}
function isComponentSharedEdgeSegment(segment, componentCapacityMeshNodeIds) {
  return segment.nodeIds.some((nodeId) => componentCapacityMeshNodeIds.has(nodeId));
}
function getNonComponentSharedEdgeSegments({
  sharedEdgeSegments,
  componentCapacityMeshNodeIds
}) {
  return sharedEdgeSegments.filter((segment) => !isComponentSharedEdgeSegment(segment, componentCapacityMeshNodeIds));
}
function mergeComponentSharedEdgeSegments({
  originalSharedEdgeSegments,
  filteredSharedEdgeSegments,
  componentCapacityMeshNodeIds
}) {
  const filteredSegmentsByEdgeId = new Map(filteredSharedEdgeSegments.map((segment) => [segment.edgeId, segment]));
  return originalSharedEdgeSegments.map((segment) => {
    if (isComponentSharedEdgeSegment(segment, componentCapacityMeshNodeIds)) {
      return segment;
    }
    return filteredSegmentsByEdgeId.get(segment.edgeId) ?? segment;
  });
}
function definePipelineStep3(solverName, solverClass, getConstructorParams, opts = {}) {
  return {
    solverName,
    solverClass,
    getConstructorParams,
    onSolved: opts.onSolved
  };
}

